mapper.select:
SELECT COALESCE(MAX(version_no), 0) + 1
FROM squad_chat.sq_mcp_server_version
WHERE mcp_server_id = #{mcpServerId}

mapper.update:
UPDATE squad_chat.sq_mcp_server_version
SET status           = 'PUBLISHED',
    revision         = revision + 1,
    published_at     = CURRENT_TIMESTAMP,
    last_updater_id  = #{lastUpdaterId},
    last_update_time = CURRENT_TIMESTAMP
WHERE mcp_server_id = #{mcpServerId}
  AND mcp_server_version_id = #{mcpServerVersionId}
  AND status = 'DRAFT'
  AND revision = #{revision}
